import os,json,subprocess
from pathlib import Path
checks={
'/etc/lowcost-europa':'/srv/projects/lowcost-europa/private/systemd-env',
'/var/backups/lowcost-europa':'/srv/projects/lowcost-europa/backups',
'/var/lib/lowcost-europa':'/srv/projects/lowcost-europa/data'}
blocked=[]
r={'operation':'retire_only_verified_lowcost_aliases','removed':[],'status':'PREFLIGHT','preserved_central_vault':True}
def system_status():
 return {n:subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=8).stdout.strip() for n in ('ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads')}
try:
 assert os.geteuid()==0
 for alias,dest in checks.items():
  link=Path(alias);target=Path(dest)
  assert link.is_symlink() and target.is_dir() and not target.is_symlink() and link.resolve()==target,'expected alias missing or changed: '+alias
 assert Path('/root/project-secrets').is_dir(),'protected vault missing'
 pre=system_status()
 assert all(v=='active' for v in pre.values()),'critical service unavailable'
 for root in ('/etc/systemd/system','/etc/nginx','/etc/cron.d','/etc/cron.daily','/etc/cron.weekly','/etc/cron.monthly','/usr/local/bin','/usr/local/sbin'):
  base=Path(root)
  if not base.is_dir():continue
  for current,dirs,files in os.walk(base,followlinks=False):
   if len(Path(current).relative_to(base).parts)>4:dirs[:]=[];continue
   for n in files:
    f=Path(current)/n
    try:
     if not f.is_file() or f.stat().st_size>500000:continue
     b=f.read_text(errors='replace')
     if any(a in b for a in checks):blocked.append(str(f))
    except OSError:pass
 for rel in ('bin','deploy/scripts'):
  base=Path('/srv/projects/lowcost-europa')/rel
  if not base.is_dir():continue
  for f in base.rglob('*'):
   try:
    if not f.is_file() or f.is_symlink() or f.stat().st_size>250000:continue
    for line in f.read_text(errors='replace').splitlines():
     if any(a in line for a in checks):
      if ('restored_env="$target/etc/lowcost-europa/' in line or
          'restored_backup_dir="$target/var/backups/lowcost-europa/' in line):
       continue
      blocked.append(str(f));break
   except OSError:pass
 # Exclude the current inspection process and its parent chain. Their
 # arguments contain this script text, not an application using the aliases.
 own=set()
 pid=os.getpid()
 while pid>1 and pid not in own:
  own.add(pid)
  try:
   st=(Path('/proc')/str(pid)/'stat').read_text()
   pid=int(st.rsplit(') ',1)[1].split()[1])
  except Exception:break
 for proc in Path('/proc').iterdir():
  if not proc.name.isdigit() or int(proc.name) in own:continue
  try:
   args=(proc/'cmdline').read_bytes().decode(errors='replace')
   if any(a in args for a in checks):blocked.append('unrelated process using legacy alias')
  except OSError:pass
 assert not blocked,'alias consumers remain'
 for alias,dest in checks.items():
  Path(alias).unlink()
  r['removed'].append(alias)
 after=system_status()
 assert all(v=='active' for v in after.values()),'critical service changed'
 assert all(not Path(a).exists() and not Path(a).is_symlink() for a in checks),'alias still present'
 assert Path('/root/project-secrets').is_dir()
 r.update({'status':'REMOVED_VERIFIED','services_unchanged':pre==after,'aliases_removed':len(r['removed'])})
except Exception as e:
 r.update({'status':'NOT_COMPLETED','reason':type(e).__name__+': '+str(e)[:210],'blocked_consumers_count':len(blocked),'blocked_consumer_paths':blocked[:12]})
 for alias in reversed(r['removed']):
  try:Path(alias).symlink_to(checks[alias])
  except Exception:r.setdefault('rollback_failed',[]).append(alias)
print(json.dumps(r,separators=(',',':')))
